resource "aws_iam_role" "bedrock_agent_role" {
  name               = "bedrock_agent_basic_role_${var.cgid}"
  assume_role_policy = jsonencode({
    Version   = "2012-10-17",
    Statement = [
      {
        Action    = "sts:AssumeRole",
        Effect    = "Allow",
        Principal = {
          Service = "bedrock.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "bedrock_agent_policy" {
  name   = "bedrock_agent_basic_role_policy_${var.cgid}"
  role   = aws_iam_role.bedrock_agent_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "bedrock:InvokeModel",
          "bedrock:InvokeModelWithResponseStream"
        ]
        Resource = "arn:aws:bedrock:${var.region}::foundation-model/${var.agent_model_id}"
      }
    ]
  })
}

resource "aws_bedrockagent_agent" "operations_agent" {
  agent_name              = "operations_agent_${var.cgid}"
  agent_resource_role_arn = aws_iam_role.bedrock_agent_role.arn
  description = "A simple Bedrock Agent that can inventory cloud resources."
  idle_session_ttl_in_seconds = 300

  instruction = <<-EOT
You are a helpful cloud assistant that answers user questions about AWS concisely.
If you don't know the answer, say you don't know rather than making something up.
Use your tools to inventory live cloud resources if required.
EOT

  # Some foundation model providers like anthropic require additional setup. Nova shouldn't
  foundation_model = var.agent_model_id
}

resource "aws_bedrockagent_agent_action_group" "inventory_tool" {
  agent_id      = aws_bedrockagent_agent.operations_agent.id
  agent_version = "DRAFT"
  action_group_name = "InventoryTool"
  description = "Action group exposing lambda function that inventories cloud resources"
  skip_resource_in_use_check = true
  action_group_executor {
    lambda = aws_lambda_function.inventory_lambda.arn
  }
  function_schema {
    member_functions {
      functions {
        name        = "LIST_IAM_ROLES"
        description = "Lists up to 100 IAM roles in the current account"
      }
      functions {
        name        = "LIST_IAM_USERS"
        description = "Lists up to 100 IAM users in the current account"
      }
      functions {
        name        = "LIST_EC2_INSTANCES"
        description = "Lists up to 100 EC2 instances in the current account"
      }
      functions {
        name        = "LIST_S3_BUCKETS"
        description = "Lists up to 100 S3 buckets in the current account"
      }
      functions {
        name        = "LIST_ALL"
        description = "Provides a listing of IAM roles, users, EC2 instances, and S3 Buckets in the current account"
      }
    }
  }
}

#############################
# Starting User (Initial Credentials)
#############################

resource "aws_iam_user" "starting_user" {
  name = "grace_${var.cgid}"
}

resource "aws_iam_access_key" "starting_user_key" {
  user = aws_iam_user.starting_user.name
}

# Iam enumeration is not part of the challenge. Might as well make it easy
resource "aws_iam_user_policy_attachment" "starting_user_iam_policy_attachment" {
  user       = aws_iam_user.starting_user.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_policy" "starting_user_bedrock_policy" {
  name = "agent_access_policy_${var.cgid}"
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Sid    = "BedrockReadOnly"
        Effect = "Allow"
        Action = [
          "bedrock:Get*",
          "bedrock:List*"
        ],
        Resource = "*"
      },
      {
        Sid    = "InvokeOperationsAgent"
        Effect = "Allow",
        Action = [
          "bedrock:InvokeAgent"
        ],
        Resource = "arn:aws:bedrock:${var.region}:${data.aws_caller_identity.aws-account-id.account_id}:agent-alias/${aws_bedrockagent_agent.operations_agent.agent_id}/*"
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "starting_user_bedrock_policy_attachment" {
  user       = aws_iam_user.starting_user.name
  policy_arn = aws_iam_policy.starting_user_bedrock_policy.arn
}

resource "aws_iam_policy" "starting_user_deployment_policy" {
  name = "lambda_deployment_policy_${var.cgid}"
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Sid    = "LambdaUpdateAccess"
        Effect = "Allow",
        Action = [
          "lambda:CreateAlias",
          "lambda:GetAlias",
          "lambda:GetFunction",
          "lambda:GetFunctionConfiguration",
          "lambda:ListAliases",
          "lambda:ListVersionsByFunction",
          "lambda:PublishVersion",
          "lambda:UpdateAlias",
          "lambda:UpdateFunctionCode",
          "lambda:UpdateFunctionConfiguration"
        ],
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "starting_user_deployment_policy_attachment" {
  user       = aws_iam_user.starting_user.name
  policy_arn = aws_iam_policy.starting_user_deployment_policy.arn
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role_${var.cgid}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action = "sts:AssumeRole",
        Effect = "Allow",
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "lambda_execution_role_log_policy" {
  role   = aws_iam_role.lambda_execution_role.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:${var.region}:${data.aws_caller_identity.aws-account-id.account_id}:log-group:/aws/lambda/inventory_lambda_${var.cgid}:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_execution_role_policy_attach" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

data "archive_file" "inventory_lambda_zip" {
  type        = "zip"
  source_dir  = "lambda_source"
  output_path = "lambda_source.zip"
}

resource "aws_cloudwatch_log_group" "inventory_lambda_log_group" {
  name              = "/aws/lambda/inventory_lambda_${var.cgid}"
  retention_in_days = 14
}

resource "aws_lambda_function" "inventory_lambda" {
  depends_on = [
    aws_cloudwatch_log_group.inventory_lambda_log_group
  ]

  filename         = data.archive_file.inventory_lambda_zip.output_path
  function_name    = "inventory_lambda_${var.cgid}"
  role             = aws_iam_role.lambda_execution_role.arn
  handler          = "main.handler"
  description      = "This function will perform an inventory of one of several resource types in AWS: IAM Roles, IAM Users, EC2 Instances, and S3 Buckets"
  source_code_hash = filebase64sha256(data.archive_file.inventory_lambda_zip.output_path)
  runtime          = "python3.9"
}

resource "aws_lambda_permission" "allow_agent_invokation" {
  statement_id  = "AllowAgent"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.inventory_lambda.function_name
  principal     = "bedrock.amazonaws.com"
  source_arn    = aws_bedrockagent_agent.operations_agent.agent_arn
}

#AWS Account ID
output "cloudgoat_output_aws_account_id" {
  value = data.aws_caller_identity.aws-account-id.account_id
}
output "scenario_cg_id" {
  value = var.cgid
}

#IAM User Credentials
output "access_key_id" {
  value = aws_iam_access_key.starting_user_key.id
}
output "secret_access_key" {
  value     = aws_iam_access_key.starting_user_key.secret
  sensitive = true
}

## This is used for the CloudGoat scenario to pull the AWS profile from the CloudGoat configuration.
## Configure required Terraform and provider versions.

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.74.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.4"
    }
  }
}

provider "aws" {
  profile = var.profile
  region  = var.region

  # This configures default tags for all resources
  default_tags {
    tags = {
      Name     = "cg-${var.cgid}"
      Stack    = var.stack-name
      Scenario = var.scenario-name
    }
  }
}

resource "aws_s3_bucket" "target_s3_bucket" {
  bucket = "cg-bedrock-secret-flag-${replace(var.cgid, "/[^a-z0-9-.]/", "-")}"
}

resource "aws_s3_object" "target_file" {
  bucket       = aws_s3_bucket.target_s3_bucket.bucket
  key          = "flag.txt"
  content      = "FLAG{@g3nt5_h@v3_p3rm1ss10ns}"
  content_type = "text/plain"
}

variable "profile" {
  description = "The AWS profile to use"
  type        = string
}

variable "cgid" {
  description = "CGID variable for unique naming"
  type        = string
}

variable "cg_whitelist" {
  description = "User's public IP address(es)"
  type        = list(string)
}

variable "region" {
  description = "The AWS region to deploy to"
  default     = "us-east-1"
  type        = string
}

variable "stack-name" {
  description = "Name of the CloudGoat stack"
  default     = "CloudGoat"
  type        = string
}

variable "scenario-name" {
  description = "Name of the scenario"
  default     = "bedrock_agent_hijacking"
  type        = string
}

# Additional scenario-specific variables
variable "agent_model_id" {
  description = "The ID of the foundational model used by the agent."
  type        = string
  default     = "amazon.nova-lite-v1:0"
}
